-- OCR is independent of hand-written notes. Originals are immutable within one screenshot ID.
CREATE TABLE ocr_content (
 screenshot_id TEXT PRIMARY KEY REFERENCES screenshots(id) ON DELETE CASCADE,
 recognized_text TEXT NOT NULL DEFAULT '' CHECK(length(CAST(recognized_text AS BLOB))<=1048576),
 language TEXT NOT NULL, recognition_status TEXT NOT NULL CHECK(recognition_status IN ('running','completed','failed')),
 ocr_engine_version TEXT NOT NULL, updated_at INTEGER NOT NULL,
 source_image_revision TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0),
 error TEXT, corrected INTEGER NOT NULL DEFAULT 0 CHECK(corrected IN (0,1))
) STRICT;
CREATE VIRTUAL TABLE screenshot_search USING fts5(screenshot_id UNINDEXED,title,notes,tags,ocr,tokenize='trigram');
CREATE VIEW screenshot_search_source AS SELECT s.rowid AS rowid,s.id AS screenshot_id,s.title,
 coalesce((SELECT group_concat(content,char(10)) FROM (SELECT content FROM notes WHERE screenshot_id=s.id ORDER BY created_at,id)),'') AS notes,
 coalesce((SELECT group_concat(name,' ') FROM (SELECT t.name FROM screenshot_tags st JOIN tags t ON t.id=st.tag_id WHERE st.screenshot_id=s.id ORDER BY t.normalized_name,t.id)),'') AS tags,
 coalesce((SELECT recognized_text FROM ocr_content WHERE screenshot_id=s.id),'') AS ocr FROM screenshots s;
INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source;
CREATE TRIGGER search_screenshots_insert AFTER INSERT ON screenshots BEGIN DELETE FROM screenshot_search WHERE screenshot_id=new.id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=new.id; END;
CREATE TRIGGER search_screenshots_update AFTER UPDATE ON screenshots BEGIN DELETE FROM screenshot_search WHERE screenshot_id=old.id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=old.id; DELETE FROM screenshot_search WHERE screenshot_id=new.id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=new.id; END;
CREATE TRIGGER search_screenshots_delete AFTER DELETE ON screenshots BEGIN DELETE FROM screenshot_search WHERE screenshot_id=old.id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=old.id; END;
CREATE TRIGGER search_notes_insert AFTER INSERT ON notes BEGIN DELETE FROM screenshot_search WHERE screenshot_id=new.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=new.screenshot_id; END;
CREATE TRIGGER search_notes_update AFTER UPDATE ON notes BEGIN DELETE FROM screenshot_search WHERE screenshot_id=old.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=old.screenshot_id; DELETE FROM screenshot_search WHERE screenshot_id=new.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=new.screenshot_id; END;
CREATE TRIGGER search_notes_delete AFTER DELETE ON notes BEGIN DELETE FROM screenshot_search WHERE screenshot_id=old.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=old.screenshot_id; END;
CREATE TRIGGER search_screenshot_tags_insert AFTER INSERT ON screenshot_tags BEGIN DELETE FROM screenshot_search WHERE screenshot_id=new.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=new.screenshot_id; END;
CREATE TRIGGER search_screenshot_tags_update AFTER UPDATE ON screenshot_tags BEGIN DELETE FROM screenshot_search WHERE screenshot_id=old.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=old.screenshot_id; DELETE FROM screenshot_search WHERE screenshot_id=new.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=new.screenshot_id; END;
CREATE TRIGGER search_screenshot_tags_delete AFTER DELETE ON screenshot_tags BEGIN DELETE FROM screenshot_search WHERE screenshot_id=old.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=old.screenshot_id; END;
CREATE TRIGGER search_ocr_content_insert AFTER INSERT ON ocr_content BEGIN DELETE FROM screenshot_search WHERE screenshot_id=new.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=new.screenshot_id; END;
CREATE TRIGGER search_ocr_content_update AFTER UPDATE ON ocr_content BEGIN DELETE FROM screenshot_search WHERE screenshot_id=old.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=old.screenshot_id; DELETE FROM screenshot_search WHERE screenshot_id=new.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=new.screenshot_id; END;
CREATE TRIGGER search_ocr_content_delete AFTER DELETE ON ocr_content BEGIN DELETE FROM screenshot_search WHERE screenshot_id=old.screenshot_id; INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id=old.screenshot_id; END;
CREATE TRIGGER search_tags_update AFTER UPDATE OF name ON tags BEGIN
 DELETE FROM screenshot_search WHERE screenshot_id IN (SELECT screenshot_id FROM screenshot_tags WHERE tag_id=new.id);
 INSERT INTO screenshot_search(rowid,screenshot_id,title,notes,tags,ocr) SELECT * FROM screenshot_search_source WHERE screenshot_id IN (SELECT screenshot_id FROM screenshot_tags WHERE tag_id=new.id); END;
